using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<ModelTrainingService>();

// Train model at startup to produce model.zip
var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
var loggerFactory = LoggerFactory.Create(b => b.AddConsole());
var trainer = new ModelTrainingService(loggerFactory.CreateLogger<ModelTrainingService>());
trainer.TrainAndEvaluate();

// Register the pooled prediction engine with the trained model
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

